insert into public.faqs (title, slug, excerpt, body, category, tags, status, data, published_at)
values
  ('Which service is right for me?', 'which-service-is-right-for-me', '', 'Choose career support for CVs, cover letters, LinkedIn or interviews; admission or scholarship essay support for your study applications; and MBA support for a school list of at least three. If you need help choosing, [book a free 15-minute call](/consultation?mode=call).', 'Getting started', array[]::text[], 'published', jsonb_build_object('category_order', 0, 'display_order', 0), now()),
  ('What can I use for free?', 'what-can-i-use-for-free', '', 'You can browse jobs, scholarships, articles and resource tools without booking a paid service. The initial 15-minute consultation is free; document reviews, coaching and application packages are paid services. [View pricing and package terms](/services?section=pricing).', 'Getting started', array[]::text[], 'published', jsonb_build_object('category_order', 0, 'display_order', 1), now()),
  ('Can Careergrill guarantee a job, admission or scholarship?', 'can-careergrill-guarantee-a-job-admission-or-scholarship', '', 'No. We help you prepare and improve your application, but employers, universities and scholarship providers make their own decisions.', 'Getting started', array[]::text[], 'published', jsonb_build_object('category_order', 0, 'display_order', 2), now()),
  ('How do I choose between Clarity, Precision and Distinction?', 'how-do-i-choose-between-clarity-precision-and-distinction', '', 'Clarity offers fewer feedback rounds and a basic CV review; Precision adds more rounds, a detailed CV review and proofreading; Distinction includes the most rounds, a comprehensive CV review and priority support. Admission and scholarship packages have different prices and inclusions, so check the category you need. [View pricing and package terms](/services?section=pricing).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 0), now()),
  ('Can I enquire before my documents are ready?', 'can-i-enquire-before-my-documents-are-ready', '', 'Yes. Share your goal, application stage and deadline, plus any notes or drafts you have. We’ll confirm the suitable support and materials needed before work begins. [Draft a service enquiry](/consultation).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 1), now()),
  ('How long will the service take?', 'how-long-will-the-service-take', '', 'Career document first drafts are due within 72 hours of receiving your materials. Admission and scholarship essay support runs for six weeks from complete materials; MBA support runs for eight weeks. Individual admission and scholarship feedback rounds are normally returned within 24–48 business hours. [View pricing and package terms](/services?section=pricing).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 2), now()),
  ('Can you help with an urgent deadline?', 'can-you-help-with-an-urgent-deadline', '', 'Ask before paying. Admission and scholarship packages should be booked at least eight weeks before your earliest deadline; a shorter timeline needs confirmation. Priority support aims for faster feedback within business hours and does not add weekend or after-hours availability.', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 3), now()),
  ('What counts as a feedback round?', 'what-counts-as-a-feedback-round', '', 'For essay support, a round returns your submitted draft with tracked changes, comments and a written summary. Several scholarship essays submitted together count as one round; MBA essay rounds are counted per school. The number of rounds depends on your package.', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 4), now()),
  ('What happens if I need more revisions?', 'what-happens-if-i-need-more-revisions', '', 'Confirm the scope and fee for additional work before it begins. Career document services include two revision rounds used within one week of receiving the draft; requests after that week are new work and priced separately. [View pricing and package terms](/services?section=pricing).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 5), now()),
  ('When do I pay, and can I pay in instalments?', 'when-do-i-pay-and-can-i-pay-in-instalments', '', 'Career document, admission essay and scholarship essay services require full payment before work begins. MBA packages allow full payment or two instalments; the amounts and dates are agreed before payment. MBA volume discounts apply only to one-time payment. [View pricing and package terms](/services?section=pricing).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 6), now()),
  ('What if I need to cancel?', 'what-if-i-need-to-cancel', '', 'Admission and scholarship essay packages offer a full refund before the paid package consultation, 50% after that consultation but before feedback begins, and no refund after the first feedback round is delivered. MBA refunds follow the first brainstorming session and essay-feedback stages; confirm career-service cancellation terms before paying. [View pricing and package terms](/services?section=pricing).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 7), now()),
  ('How do I send my enquiry?', 'how-do-i-send-my-enquiry', '', 'Choose your service or pricing package, add your details and select Create message. Review or edit the draft, then copy it or open WhatsApp or email and send it yourself; if copying fails, the message is highlighted so you can use your device’s Copy command. [Draft a service enquiry](/consultation).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 8), now()),
  ('What is included in the free 15-minute call?', 'what-is-included-in-the-free-15-minute-call', '', 'A short conversation about your goal, deadline and the support you may need. It does not include a full CV, essay or application review. Choose a time and complete the confirmation on the booking page. [Book a free 15-minute call](/consultation?mode=call).', 'Services and pricing', array[]::text[], 'published', jsonb_build_object('category_order', 1, 'display_order', 9), now()),
  ('Is AI feedback currently available?', 'is-ai-feedback-currently-available', '', '**AI feedback availability — 21 October 2026:** AI feedback is temporarily unavailable. You can still complete and save your audit, or read existing feedback in My audits. Generation is paused, so no daily attempt is used.', 'AI Career Audit', array[]::text[], 'published', jsonb_build_object('category_order', 2, 'display_order', 0), now()),
  ('What does the AI Career Audit do?', 'what-does-the-ai-career-audit-do', '', 'It uses the information you enter to review your preparation, identify gaps and suggest next steps. You can choose a job search, master’s, PhD, scholarship or fellowship path. The feedback is guidance based on your answers, not a verified eligibility or selection decision.', 'AI Career Audit', array[]::text[], 'published', jsonb_build_object('category_order', 2, 'display_order', 1), now()),
  ('How is AI feedback different from a paid Careergrill review?', 'how-is-ai-feedback-different-from-a-paid-careergrill-review', '', 'AI generates audit feedback from the answers you share and delivers it directly to you. A paid document review or consultation involves a person at Careergrill and is arranged separately. [Draft a service enquiry](/consultation).', 'AI Career Audit', array[]::text[], 'published', jsonb_build_object('category_order', 2, 'display_order', 2), now()),
  ('Does the audit read links or my full CV automatically?', 'does-the-audit-read-links-or-my-full-cv-automatically', '', 'No. It uses the text you enter. For a job audit, paste the relevant job requirements and selected CV points; the AI does not open your links or verify employers, eligibility or deadlines.', 'AI Career Audit', array[]::text[], 'published', jsonb_build_object('category_order', 2, 'display_order', 3), now()),
  ('What happens if AI feedback fails to generate?', 'what-happens-if-ai-feedback-fails-to-generate', '', 'Your saved draft stays in My audits. Keep a copy of your answers and return when the service is available; contact Careergrill if the problem continues. Reading existing feedback does not require a new assessment.', 'AI Career Audit', array[]::text[], 'published', jsonb_build_object('category_order', 2, 'display_order', 4), now()),
  ('Is there a limit on AI feedback?', 'is-there-a-limit-on-ai-feedback', '', 'When generation is available, each account can make up to five generation attempts per day, subject to capacity. Failed attempts count, but opening saved feedback does not. A known service pause blocks generation before it uses an attempt.', 'AI Career Audit', array[]::text[], 'published', jsonb_build_object('category_order', 2, 'display_order', 5), now()),
  ('Can I change my answers after receiving feedback?', 'can-i-change-my-answers-after-receiving-feedback', '', 'Yes. Open the saved audit and choose Edit answers. Saving changed answers replaces the earlier AI result, so download feedback you want to keep before editing. Generate a new assessment when the service is available.', 'AI Career Audit', array[]::text[], 'published', jsonb_build_object('category_order', 2, 'display_order', 6), now()),
  ('Does a search result mean I am eligible?', 'does-a-search-result-mean-i-am-eligible', '', 'No. Search filters and preference matches narrow the directory; they do not confirm eligibility. Check the employer’s or provider’s current requirements, location restrictions, funding coverage and deadline before applying.', 'Jobs and scholarships', array[]::text[], 'published', jsonb_build_object('category_order', 3, 'display_order', 0), now()),
  ('What does “Status needs checking” mean?', 'what-does-status-needs-checking-mean', '', 'The current application cycle or key details have not been confirmed. Treat the listing as a research lead and check the official source. Featured scholarships use checked source information, but availability can change.', 'Jobs and scholarships', array[]::text[], 'published', jsonb_build_object('category_order', 3, 'display_order', 1), now()),
  ('Does saving an opportunity submit my application?', 'does-saving-an-opportunity-submit-my-application', '', 'No. Saving adds the opportunity to your account’s shortlist. Apply through the employer or scholarship provider, then update your workspace stage yourself.', 'Jobs and scholarships', array[]::text[], 'published', jsonb_build_object('category_order', 3, 'display_order', 2), now()),
  ('Where can I find my saved opportunities?', 'where-can-i-find-my-saved-opportunities', '', 'Open Workspace and choose My saved jobs or My saved scholarships. Sign in to return to your saved opportunities, application notes and progress. You can also open [My audits](/my-audits) for saved audits and feedback.', 'Jobs and scholarships', array[]::text[], 'published', jsonb_build_object('category_order', 3, 'display_order', 3), now()),
  ('Do I need to sign in?', 'do-i-need-to-sign-in', '', 'You can browse opportunities and resources, prepare an enquiry and start an audit without signing in. Sign in to save opportunities, application notes and audits to your account, or generate AI feedback when available.', 'Accounts and privacy', array[]::text[], 'published', jsonb_build_object('category_order', 4, 'display_order', 0), now()),
  ('Will my drafts and worksheet notes be saved?', 'will-my-drafts-and-worksheet-notes-be-saved', '', 'Unsaved audit drafts, enquiry drafts and resource worksheet notes stay in the current browser tab through reloads; they do not automatically sync across devices and can be lost when the session ends. Download or copy important work before closing the tab. Account-saved audits and application notes are kept separately.', 'Accounts and privacy', array[]::text[], 'published', jsonb_build_object('category_order', 4, 'display_order', 1), now()),
  ('Who can see my documents and audit answers?', 'who-can-see-my-documents-and-audit-answers', '', 'Careergrill uses hosting and AI providers to operate the site. When you request AI feedback, the answers you enter are sent to the AI provider; leave out identification numbers, contact details and confidential information about other people. Arrange document sharing privately after agreeing a personal review. [Read the privacy information](/privacy).', 'Accounts and privacy', array[]::text[], 'published', jsonb_build_object('category_order', 4, 'display_order', 2), now()),
  ('Can I delete my saved information?', 'can-i-delete-my-saved-information', '', 'You can delete individual audits in My audits and remove saved opportunities from your workspace. For a copy or removal of other account-linked information, email [info@careergrill.com](mailto:info@careergrill.com). [Read the privacy information](/privacy).', 'Accounts and privacy', array[]::text[], 'published', jsonb_build_object('category_order', 4, 'display_order', 3), now())
